<template><div><div class="page-title"><div><div class="eyebrow">VULNERABILITY INTELLIGENCE</div><h2>CVE 漏洞情报</h2></div><el-button type="primary" :loading="syncing" @click="sync">同步 NVD</el-button></div><el-form inline class="section-card"><el-input v-model="keyword" clearable placeholder="搜索 CVE 或漏洞名称" @keyup.enter="load"/><el-select v-model="severity" clearable placeholder="风险等级"><el-option v-for="item in ['critical','high','medium','low','info']" :key="item" :label="item" :value="item"/></el-select><el-button @click="load">查询</el-button></el-form><div v-loading="loading" class="table-wrap"><el-table :data="items"><el-table-column prop="cve_id" label="CVE 编号" width="170"/><el-table-column prop="title" label="漏洞名称" min-width="300" show-overflow-tooltip/><el-table-column prop="severity" label="等级" width="100"><template #default="{row}"><el-tag :type="tag(row.severity)">{{row.severity}}</el-tag></template></el-table-column><el-table-column prop="cvss_score" label="CVSS" width="90"/><el-table-column label="影响产品" min-width="230" show-overflow-tooltip><template #default="{row}">{{row.affected_products.slice(0,2).join(', ')||'暂无 CPE'}}</template></el-table-column><el-table-column prop="last_modified_at" label="更新时间" width="190"/><el-table-column label="操作" width="80"><template #default="{row}"><el-button link type="primary" @click="detail(row)">详情</el-button></template></el-table-column></el-table><el-empty v-if="!loading&&!items.length" description="暂无 CVE 情报，请先执行同步"/></div><el-pagination v-if="total" class="section-card" layout="prev, pager, next" :page-size="20" :total="total" v-model:current-page="page" @current-change="load"/><el-drawer v-model="visible" title="CVE 情报详情" size="560px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="CVE">{{selected.cve_id}}</el-descriptions-item><el-descriptions-item label="名称">{{selected.title}}</el-descriptions-item><el-descriptions-item label="等级 / CVSS">{{selected.severity}} / {{selected.cvss_score??'暂无'}}</el-descriptions-item><el-descriptions-item label="发布时间">{{selected.published_at||'暂无'}}</el-descriptions-item><el-descriptions-item label="描述">{{selected.description||'暂无描述'}}</el-descriptions-item><el-descriptions-item label="参考链接"><div v-for="link in selected.references" :key="link"><a :href="link" target="_blank">{{link}}</a></div></el-descriptions-item></el-descriptions></el-drawer></div></template>
<script setup lang="ts">import { onMounted, ref } from "vue";import { ElMessage } from "element-plus";import client from "../api/client";import type { CveIntelligence } from "../api/types";const items=ref<CveIntelligence[]>([]),selected=ref<CveIntelligence|null>(null),visible=ref(false),loading=ref(false),syncing=ref(false),total=ref(0),page=ref(1),keyword=ref(""),severity=ref("");const load=async()=>{loading.value=true;try{const r=(await client.get("/cve",{params:{page:page.value,page_size:20,keyword:keyword.value||undefined,severity:severity.value||undefined}})).data;items.value=r.data;total.value=r.total;}catch{items.value=[];}finally{loading.value=false;}};const sync=async()=>{syncing.value=true;try{await client.post("/cve/sync");ElMessage.success("同步任务已提交后台队列");}catch{ElMessage.error("同步提交失败，请确认管理员权限和队列状态");}finally{syncing.value=false;}};const detail=(row:CveIntelligence)=>{selected.value=row;visible.value=true};const tag=(s:string)=>s==='critical'?'danger':s==='high'?'warning':s==='medium'?'':'info';onMounted(load);</script>
